fn pairwise_addition(a: Vec<i64>) -> Vec<i64> {
    // The input length must be even.
    assert!(a.len() % 2 == 0, "Input vector must have even length");

    let half_len = a.len() / 2;
    let mut result = Vec::with_capacity(half_len);

    // Sum each consecutive pair a[2*i] + a[2*i + 1]
    for i in 0..half_len {
        let sum = a[2 * i] + a[2 * i + 1];
        result.push(sum);
    }

    result
}

